#!/usr/bin/env python3
"""Retain a native ABI baseline from a C header, measured by a C compiler.

Reads a generated header (include/crabby.h at the revision being recorded),
compiles a small C program against it with the system C compiler, and writes
what the compiler says: the size, alignment and field offsets of every struct
the header defines, the value of every enum constant and numeric #define, and
the ABI version. The numbers come from a C compiler reading the header, not
from the Rust code under test.

It also writes `layout_table.rs`, the Rust side of the comparison: for each
struct, enum and constant named in the header, how to read the same fact from
the Rust types. It holds no numbers.

Usage (see README.md in this folder):
    python3 generate_baseline.py <header> <out-dir> <abi-version>

It refuses to overwrite existing files: baselines are never regenerated.
"""
import json
import os
import re
import subprocess
import sys
import tempfile
from pathlib import Path


def main():
    header, out_dir, abi_version = Path(sys.argv[1]), Path(sys.argv[2]), int(sys.argv[3])
    text = header.read_text()
    structs = []  # (name, [field])
    for name, body in re.findall(r"typedef struct (\w+) \{\n(.*?)\n\} \1;", text, re.S):
        fields = []
        for line in body.split("\n"):
            m = re.match(r"^\s*[\w \*]+?[ \*](\w+)(?:\[\w+\])?;$", line)
            if not m:
                sys.exit(f"can't read field of {name}: {line!r}")
            fields.append(m.group(1))
        structs.append((name, fields))
    enums = []  # (name, [constant])
    for name, body in re.findall(r"typedef enum (\w+) \{\n(.*?)\n\} \1;", text, re.S):
        consts = [m.group(1) for m in re.finditer(r"^\s*(\w+)(?: = [^,]+)?,$", body, re.M)]
        enums.append((name, consts))
    defines = re.findall(r"^#define (CRABBY_[A-Z0-9_]+) \S+$", text, re.M)
    defines = [d for d in defines if d != "CRABBY_H"]

    c = [f'#include "{header.name}"', "#include <stdio.h>", "#include <stddef.h>", "int main(void) {"]
    c.append('printf("{\\n");')
    c.append(f'printf("  \\"abi_version\\": {abi_version},\\n");')
    c.append('printf("  \\"pointer_bits\\": %d,\\n", (int)(sizeof(void*) * 8));')
    c.append('printf("  \\"structs\\": {\\n");')
    for i, (name, fields) in enumerate(structs):
        offs = ", ".join(f'\\"{f}\\": %zu' for f in fields)
        args = ", ".join(f"offsetof({name}, {f})" for f in fields)
        comma = "," if i + 1 < len(structs) else ""
        c.append(
            f'printf("    \\"{name}\\": {{\\"size\\": %zu, \\"align\\": %zu, \\"offsets\\": {{{offs}}}}}{comma}\\n", '
            f"sizeof({name}), _Alignof({name}), {args});"
        )
    c.append('printf("  },\\n");')
    c.append('printf("  \\"enums\\": {\\n");')
    for i, (name, consts) in enumerate(enums):
        vals = ", ".join(f'\\"{k}\\": %lld' for k in consts)
        args = ", ".join(f"(long long){k}" for k in consts)
        comma = "," if i + 1 < len(enums) else ""
        c.append(f'printf("    \\"{name}\\": {{{vals}}}{comma}\\n", {args});')
    c.append('printf("  },\\n");')
    c.append('printf("  \\"constants\\": {\\n");')
    for i, d in enumerate(defines):
        comma = "," if i + 1 < len(defines) else ""
        c.append(f'printf("    \\"{d}\\": %llu{comma}\\n", (unsigned long long){d});')
    c.append('printf("  }\\n}\\n");')
    c.append("return 0; }")

    with tempfile.TemporaryDirectory() as tmp:
        src, exe = Path(tmp) / "layout.c", Path(tmp) / "layout"
        src.write_text("\n".join(c) + "\n")
        cc = os.environ.get("CC", "cc")
        subprocess.run([cc, "-std=c11", "-Wall", f"-I{header.parent}", str(src), "-o", str(exe)], check=True)
        result = subprocess.run([str(exe)], check=True, capture_output=True, text=True).stdout
    data = json.loads(result)

    rs = [
        "// Generated by generate_baseline.py: how to read, from the Rust types, the",
        "// facts the baseline records. It holds no numbers; do not edit by hand.",
        "// The macros are defined in abi_compat.rs.",
        "",
    ]
    rs += ["macro_rules! baseline_table {", "    () => {"]
    for name, fields in structs:
        # cbindgen appends `_` to field names that are C++ keywords (`delete_`).
        rs.append(f"        s!({name}: {', '.join(f.rstrip('_') for f in fields)});")
    for name, consts in enums:
        rs.append(f"        e!({name}: {', '.join(consts)});")
    rs.append(f"        c!({', '.join(defines)});")
    rs += ["    };", "}", ""]

    json_out, rs_out = out_dir / f"abi_v{abi_version}_layout.json", out_dir / "layout_table.rs"
    for p in (json_out, rs_out):
        if p.exists():
            sys.exit(f"{p} exists; baselines are never overwritten")
    def one_per_line(section):
        rows = [f"    {json.dumps(k)}: {json.dumps(v)}" for k, v in data[section].items()]
        return "{\n" + ",\n".join(rows) + "\n  }"

    head = {k: data[k] for k in ("abi_version", "pointer_bits")}
    body = ",\n".join(f"  {json.dumps(k)}: {one_per_line(k)}" for k in ("structs", "enums", "constants"))
    json_out.write_text("{\n" + ",\n".join(f"  {json.dumps(k)}: {v}" for k, v in head.items()) + ",\n" + body + "\n}\n")
    rs_out.write_text("\n".join(rs))


main()
